package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for KeyedObjects2D.removeRow(Comparable).
 */
public class KeyedObjects2D_removeRow_TriageGen2Test {

    private KeyedObjects2D keyedObjects2D;

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    /**
     * Tests that removeRow throws UnknownKeyException when the key is not found.
     * This covers the branch where index < 0.
     */
    @Test(expected = UnknownKeyException.class)
    public void testRemoveRow_UnknownKeyThrowsException() {
        Comparable invalidKey = "NonExistentKey";
        // Since the list is empty, getRowIndex will return -1
        keyedObjects2D.removeRow(invalidKey);
    }

    /**
     * Tests the behavior when the row key is valid.
     * Note: Based on the provided source code, the method currently does nothing 
     * after the index check if the index is valid (it only has a semicolon).
     * This test ensures the method completes successfully for a valid key.
     */
    @Test
    public void testRemoveRow_ValidKeyCompletesSuccessfully() {
        Comparable rowKey = "Row1";
        Comparable colKey = "Col1";
        Object value = "TestData";

        // Setup: Add data so that getRowIndex(rowKey) returns a non-negative value
        keyedObjects2D.addObject(value, rowKey, colKey);

        // Verify key exists
        assertEquals(0, keyedObjects2D.getRowIndex(rowKey));

        // Execute: Should not throw exception
        try {
            keyedObjects2D.removeRow(rowKey);
        } catch (Exception e) {
            fail("removeRow should not throw an exception for a valid key. Exception: " + e.getMessage());
        }
    }

    /**
     * Tests the behavior with a null key. 
     * Depending on implementation of getRowIndex, this usually results in index < 0.
     */
    @Test(expected = UnknownKeyException.class)
    public void testRemoveRow_NullKeyThrowsException() {
        keyedObjects2D.removeRow(null);
    }
}
